#include <cstddef>
#include <initializer_list>

class IntList
{
public:
    explicit IntList(std::size_t size) : m_data{ new int[size]{} }, m_size{ size } {}
    ~IntList() { delete[] m_data; }
    IntList(const IntList&) = delete;
    IntList& operator=(const IntList&) = delete;

    IntList(std::initializer_list<int> values) : IntList(values.size())
    {
        std::size_t i{ 0 };
        for (int value : values)
        {
            m_data[i++] = value;
        }
    }

    int* begin() { return m_data; }
    int* end() { return m_data + m_size; }
    const int* begin() const { return m_data; }
    const int* end() const { return m_data + m_size; }

    std::size_t size() const { return m_size; }

private:
    int* m_data{ nullptr };
    std::size_t m_size{ 0 };
};

unitTests:
TEST("built from a braced list") { const IntList list{ 3, 1, 4, 1, 5 }; CHECK_EQ(list.size(), 5u); }
TEST("range-for reads the elements in order") { const IntList list{ 3, 1, 4 }; std::string seen; for (int v : list) seen += std::to_string(v); CHECK_EQ(seen, "314"); }
TEST("range-for can change the elements") { IntList list{ 1, 2, 3 }; for (int& v : list) v *= 10; int total{ 0 }; for (int v : list) total += v; CHECK_EQ(total, 60); }
TEST("round brackets still mean a size") { const IntList zeros(4); CHECK_EQ(zeros.size(), 4u); int total{ 0 }; for (int v : zeros) total += v; CHECK_EQ(total, 0); }
TEST("no leaks") { CHECK_NO_LEAK(IntList a{ 1, 2, 3 }; IntList b(100)); }

